content:
:root {
  color-scheme: dark;
  --void: #030503;
  --shell: #1b1a15;
  --shell-edge: #343027;
  --screen: #061009;
  --screen-deep: #020805;
  --phosphor: #70ff89;
  --phosphor-soft: #b6ffc0;
  --muted: #78a982;
  --amber: #f0b85c;
  --fault: #ff665f;
  --line: rgba(112, 255, 137, .38);
  --line-soft: rgba(112, 255, 137, .16);
  --glow: 0 0 18px rgba(112, 255, 137, .18);
  --mono: "Cascadia Mono", "SFMono-Regular", Consolas, "Liberation Mono", monospace;
}

* { box-sizing: border-box; }

html {
  min-width: 320px;
  min-height: 100%;
  background: var(--void);
}

body {
  margin: 0;
  min-height: 100vh;
  overflow-x: hidden;
  font-family: var(--mono);
  color: var(--phosphor);
  background:
    radial-gradient(circle at 50% 40%, rgba(41, 57, 31, .18), transparent 38rem),
    linear-gradient(145deg, #090a08, #020302 65%);
}

button, input { font: inherit; }

a { color: inherit; }

.skip-link {
  position: fixed;
  z-index: 100;
  top: .75rem;
  left: .75rem;
  padding: .7rem 1rem;
  color: var(--void);
  background: var(--phosphor);
  transform: translateY(-160%);
}

.skip-link:focus { transform: translateY(0); }

.device-shell {
  position: relative;
  display: grid;
  grid-template-columns: clamp(38px, 6vw, 92px) minmax(0, 1fr) clamp(38px, 6vw, 92px);
  width: min(1540px, calc(100% - 24px));
  min-height: min(920px, calc(100vh - 24px));
  margin: 12px auto;
  padding: 14px;
  border: 1px solid #4a4436;
  border-radius: 30px;
  background:
    linear-gradient(115deg, transparent 18%, rgba(255,255,255,.035) 25%, transparent 34%),
    repeating-linear-gradient(96deg, rgba(255,255,255,.018) 0 1px, transparent 1px 7px),
    #191813;
  box-shadow:
    inset 0 0 0 4px #0c0d0a,
    inset 0 0 0 6px #2d2a22,
    0 28px 90px rgba(0,0,0,.72);
}

.device-shell::before,
.device-shell::after {
  content: "";
  position: absolute;
  width: 17px;
  height: 17px;
  border: 2px solid #080906;
  border-radius: 50%;
  background: radial-gradient(circle, #3d392d 0 24%, #11120e 26% 60%, #29261f 62%);
  box-shadow: 0 0 0 1px #4a4437;
}

.device-shell::before { inset: 17px auto auto 17px; }
.device-shell::after { inset: auto 17px 17px auto; }

.hardware {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 22px;
  color: var(--amber);
  font-size: 10px;
  letter-spacing: .12em;
}

.hardware-left { flex-direction: column; }

.hardware-right {
  flex-direction: column;
  padding-inline: 8px;
}

.hardware-right span {
  display: grid;
  place-items: center;
  width: 100%;
  min-height: 42px;
  border: 1px solid #080906;
  border-radius: 7px;
  background: linear-gradient(#24231d, #0d0e0b);
  box-shadow: inset 0 0 0 2px #343127, 0 3px 6px #050604;
}

.vent {
  width: 54px;
  height: 52px;
  opacity: .8;
  background: repeating-linear-gradient(to bottom, #050604 0 5px, transparent 5px 11px);
}

.power-lamp {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--amber);
  box-shadow: 0 0 15px var(--amber);
}

.dial {
  width: 46px;
  height: 46px;
  border: 4px solid #0a0b08;
  border-radius: 50%;
  background:
    linear-gradient(110deg, transparent 46%, var(--amber) 48% 52%, transparent 54%),
    radial-gradient(circle, #29271f 0 45%, #0e0f0c 47% 70%, #3b372b 72%);
  box-shadow: 0 0 0 1px #474235;
}

.crt {
  position: relative;
  isolation: isolate;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  min-width: 0;
  padding: clamp(18px, 3vw, 42px);
  overflow: hidden;
  border: 12px solid #080a07;
  border-radius: 56px / 34px;
  background:
    radial-gradient(ellipse at center, rgba(31, 95, 49, .17), transparent 67%),
    linear-gradient(180deg, #07130a, var(--screen-deep));
  box-shadow:
    inset 0 0 90px rgba(0,0,0,.92),
    inset 0 0 24px rgba(112,255,137,.12),
    0 0 0 2px #353226;
}

.crt::before {
  content: "";
  position: absolute;
  z-index: 9;
  inset: 0;
  pointer-events: none;
  background: repeating-linear-gradient(to bottom, rgba(255,255,255,.025) 0 1px, rgba(0,0,0,.08) 1px 4px);
  mix-blend-mode: screen;
  animation: scan-drift 7s linear infinite;
}

.crt::after {
  content: "";
  position: absolute;
  z-index: 8;
  inset: -8%;
  pointer-events: none;
  background: radial-gradient(ellipse, transparent 48%, rgba(0,0,0,.72) 82%);
}

 .signal-canvas {
  position: absolute;
  z-index: 6;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  mix-blend-mode: screen;
  opacity: .92;
}

.crt[data-signal-renderer="webgpu"] .glass-noise,
.crt[data-signal-renderer="webgl2"] .glass-noise {
  opacity: .025;
}

.glass-noise {
  position: absolute;
  z-index: 7;
  inset: 0;
  pointer-events: none;
  opacity: .08;
  background-image:
    repeating-radial-gradient(circle at 22% 17%, transparent 0 2px, rgba(112,255,137,.25) 3px, transparent 4px);
  background-size: 83px 61px;
  animation: noise-shift .24s steps(2) infinite;
}

.terminal-header,
.terminal-grid,
.system-footer {
  position: relative;
  z-index: 10;
}

.terminal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding-bottom: 18px;
  border-bottom: 1px solid var(--line);
}

.brand {
  text-decoration: none;
  font-size: clamp(31px, 5.2vw, 76px);
  font-weight: 800;
  line-height: .92;
  letter-spacing: .055em;
  text-shadow: 0 0 18px rgba(112,255,137,.38);
}

.node-status {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 10px 16px;
  border: 1px solid var(--line);
  clip-path: polygon(8px 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%, 0 8px);
  font-size: 12px;
  letter-spacing: .12em;
}

.status-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--amber);
  box-shadow: 0 0 11px currentColor;
}

[data-terminal-state="ready"] .status-dot { background: var(--phosphor); }

.terminal-grid {
  display: grid;
  grid-template-columns: minmax(190px, .34fr) minmax(0, 1fr);
  min-height: 0;
  gap: clamp(16px, 2.4vw, 34px);
  padding-block: clamp(20px, 3vw, 38px);
}

.route-rail {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.route {
  display: grid;
  grid-template-columns: 32px 1fr auto;
  align-items: center;
  min-height: 64px;
  padding: 0 16px;
  border: 1px solid var(--line);
  text-decoration: none;
  letter-spacing: .055em;
  background: rgba(3, 12, 6, .58);
  transition: color .14s ease, background .14s ease, transform .14s ease, box-shadow .14s ease;
}

.route:hover,
.route:focus-visible,
.route.is-active {
  outline: none;
  color: #d4ffda;
  background: rgba(67, 178, 87, .18);
  box-shadow: inset 4px 0 var(--phosphor), var(--glow);
  transform: translateX(3px);
}

.route-index {
  color: var(--muted);
  font-size: 10px;
}

.terminal-panel {
  display: grid;
  grid-template-rows: minmax(390px, 1fr) auto;
  min-width: 0;
  border: 1px solid var(--line);
  background: rgba(1, 8, 4, .42);
}

.terminal-output {
  min-width: 0;
  padding: clamp(18px, 2.4vw, 32px);
  outline: none;
}

.boot-log {
  display: grid;
  gap: 7px;
  margin: 0 0 26px;
  padding: 0 0 24px;
  border-bottom: 1px solid var(--line-soft);
  list-style: none;
  color: var(--muted);
  font-size: clamp(11px, 1.1vw, 14px);
}

.boot-log li {
  opacity: 0;
  transform: translateY(4px);
}

.boot-log li.is-visible {
  opacity: 1;
  transform: translateY(0);
  transition: opacity .22s ease, transform .22s ease;
}

.boot-log span { color: var(--phosphor); }

.transmission-heading {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  color: var(--phosphor);
  font-size: 11px;
  letter-spacing: .12em;
}

.transmission-heading p { margin: 0; }
.transmission-heading span { color: var(--amber); }

.transmission-body {
  display: grid;
  grid-template-columns: 112px 1fr;
  gap: 24px;
  align-items: center;
  margin-top: 17px;
}

.transmission h2 {
  margin: 0 0 10px;
  color: var(--phosphor-soft);
  font-size: clamp(20px, 2.4vw, 34px);
  letter-spacing: .025em;
}

.transmission p {
  max-width: 690px;
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.75;
}

.transmission a {
  display: inline-block;
  margin-top: 17px;
  color: var(--amber);
  font-size: 12px;
  letter-spacing: .08em;
  text-decoration-thickness: 1px;
  text-underline-offset: 5px;
}

.artifact-glyph {
  position: relative;
  aspect-ratio: 1;
  border: 1px solid var(--line);
  background:
    linear-gradient(30deg, transparent 48%, var(--line) 49% 51%, transparent 52%),
    linear-gradient(-30deg, transparent 48%, var(--line) 49% 51%, transparent 52%);
  animation: glyph-pulse 4s ease-in-out infinite;
}

.artifact-glyph span {
  position: absolute;
  inset: 20%;
  border: 1px solid var(--phosphor);
  transform: rotate(30deg) skewY(-10deg);
}

.artifact-glyph span:nth-child(2) { inset: 31%; transform: rotate(90deg) skewY(-10deg); }
.artifact-glyph span:nth-child(3) { inset: 42%; transform: rotate(150deg) skewY(-10deg); }

.command-line {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  border-top: 1px solid var(--line);
}

.command-line:focus-within { box-shadow: inset 0 0 18px rgba(112,255,137,.08); }

.prompt {
  padding-left: 18px;
  font-size: 26px;
}

.command-line input {
  min-width: 0;
  height: 62px;
  border: 0;
  outline: 0;
  color: var(--phosphor-soft);
  background: transparent;
  caret-color: var(--phosphor);
}

.command-line input::placeholder { color: #477552; }

.command-line button {
  align-self: stretch;
  min-width: 72px;
  border: 0;
  border-left: 1px solid var(--line);
  color: var(--amber);
  background: rgba(240,184,92,.055);
  cursor: pointer;
}

.command-line button:hover,
.command-line button:focus-visible {
  outline: 1px solid var(--amber);
  outline-offset: -4px;
  background: rgba(240,184,92,.12);
}

.command-result {
  margin: 10px 0 0;
  padding: 10px 12px;
  border-left: 2px solid var(--amber);
  color: var(--phosphor-soft);
  background: rgba(240,184,92,.055);
  font-size: 12px;
  line-height: 1.65;
}

.system-footer {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border: 1px solid var(--line-soft);
  font-size: 10px;
  letter-spacing: .08em;
}

.system-footer > span,
.system-footer > button {
  min-width: 0;
  padding: 9px 12px;
  border: 0;
  border-right: 1px solid var(--line-soft);
  color: var(--phosphor);
  background: transparent;
  font-size: 10px;
  letter-spacing: .08em;
  text-align: center;
}

.system-footer > button {
  cursor: pointer;
}

.system-footer > button:hover,
.system-footer > button:focus-visible,
.system-footer > button[aria-pressed="true"] {
  outline: none;
  color: var(--amber);
  background: rgba(240,184,92,.09);
  box-shadow: inset 0 0 14px rgba(240,184,92,.08);
}

.system-footer > :last-child { border-right: 0; }
.system-footer strong { color: var(--phosphor-soft); }
.system-footer > button[aria-pressed="true"] strong {
  color: var(--amber);
  text-shadow: 0 0 10px rgba(240,184,92,.48);
}

.noscript {
  width: min(900px, calc(100% - 32px));
  margin: 12px auto;
  color: var(--amber);
  font: 13px/1.5 var(--mono);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

@keyframes scan-drift { to { transform: translateY(4px); } }
@keyframes noise-shift { 50% { transform: translate3d(-3px, 2px, 0); } }
@keyframes glyph-pulse { 50% { opacity: .68; filter: drop-shadow(0 0 8px rgba(112,255,137,.4)); } }

@media (max-width: 900px) {
  .device-shell {
    grid-template-columns: 1fr;
    width: min(100% - 12px, 760px);
    min-height: calc(100vh - 12px);
    margin: 6px auto;
    padding: 8px;
    border-radius: 20px;
  }

  .hardware { display: none; }
  .crt { padding: 24px 18px; border-width: 7px; border-radius: 30px / 22px; }
  .terminal-grid { grid-template-columns: 1fr; }
  .route-rail { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 5px; }
  .route { grid-template-columns: 1fr; min-height: 48px; padding: 8px 5px; text-align: center; font-size: 10px; }
  .route span:first-child, .route span:last-child { display: none; }
  .route:hover, .route:focus-visible, .route.is-active { transform: translateY(-2px); box-shadow: inset 0 -3px var(--phosphor); }
  .terminal-panel { grid-template-rows: auto auto; }
}

@media (max-width: 560px) {
  .terminal-header { align-items: flex-start; }
  .brand { font-size: 29px; }
  .node-status { padding: 7px 9px; font-size: 9px; }
  .crt { padding: 18px 12px; }
  .terminal-grid { padding-block: 17px; }
  .transmission-heading { display: block; }
  .transmission-heading span { display: block; margin-top: 7px; }
  .transmission-body { grid-template-columns: 72px 1fr; gap: 14px; }
  .transmission p { font-size: 11px; line-height: 1.6; }
  .system-footer { grid-template-columns: 1fr 1fr; }
  .system-footer > :nth-child(2) { border-right: 0; }
  .system-footer > :nth-child(-n+2) { border-bottom: 1px solid var(--line-soft); }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    scroll-behavior: auto !important;
    animation: none !important;
    transition: none !important;
  }

  .boot-log li { opacity: 1; transform: none; }
}
